"""The Python reference of the colour-wheel test: flowcolor.flow_colors (experiments/lib) on a 16 x 16 synthetic field.
   python wheel_reference.py <experiments/lib> <out.json>"""
import json, sys
import numpy as np
sys.path.insert(0, sys.argv[1])
from flowcolor import flow_colors
n = 16; vmax = 0.3
g = (np.arange(n) - 7.5) / 7.5 * 0.45            # lengths up to 1.5 vmax at the corners: saturation clipped there
dx, dy = np.meshgrid(g, g)                         # rows = y
dx[3, 5] = 0.0; dy[3, 5] = 0.0                     # a zero vector (white) and the axis directions (hue 0, ¼, ½, ¾)
dx[0, 8], dy[0, 8] = 0.1, 0.0; dx[1, 8], dy[1, 8] = 0.0, 0.1; dx[2, 8], dy[2, 8] = -0.1, 0.0; dx[4, 8], dy[4, 8] = 0.0, -0.1
rgb = flow_colors(dx, dy, vmax)
json.dump(dict(note="flowcolor.flow_colors(dx, dy, vmax) of experiments/lib (matplotlib hsv_to_rgb), rows = y; generated by "
                    "wheel_reference.py", vmax=vmax, dx=dx.tolist(), dy=dy.tolist(), rgb=rgb.tolist()),
          open(sys.argv[2], "w"))
print("wrote", sys.argv[2], rgb.shape)
